/*
 * COM_DATA.C  the computer player's tuning data
 *
 * Most tables are indexed by character number (row 16 serves a ranked opponent) and CPU level:
 * the attack and shell ranges of each character (Area_Unit_Data, Shell_Area_Unit_Data,
 * Dash_Distance_Data, PL_Body_Width_Data), combo speed and reaction times, wait times, guard,
 * air guard, parry and throw-escape chances (Guard_Data, Air_Guard_Data, Flip_Data,
 * Exit_Throw_Data and the rest), and the opponent move and range lists the checks test
 * against. Passive_Guard_Off_Data marks, by character and pattern, the passive patterns that
 * skip the guard check. Read by COM_PL.C, COM_SUB.C and CK_PASS.C. rival_char_tbl gives the
 * rival who breaks in against each character (SEL_PL.C and MANAGE_2.C), and
 * Correct_Cont_Time_Data the select-screen time cut after continues (SEL_PL.C).
 * Shell_Area_Step_Data is not referred to by name.
 */

